create table private.seismic_zones (
  id uuid primary key default gen_random_uuid(),
  code text not null check (char_length(code) between 1 and 40),
  city_id uuid not null references public.cities (id) on delete cascade,
  ag_g numeric(4, 2) not null check (ag_g > 0 and ag_g <= 1),
  area extensions.geography(MultiPolygon, 4326) not null,
  source text not null check (char_length(source) between 1 and 80),
  created_at timestamptz not null default now(),
  constraint seismic_zones_code_city_ag_key unique (code, city_id, ag_g)
);

comment on table private.seismic_zones is 'Zones of the design peak ground acceleration (ag, in g) of a seismic design code, clipped to the coverage area of each city; the seismic context of the SmartCheck report, never part of the zone score.';

create index seismic_zones_area_idx on private.seismic_zones using gist (area);
create index seismic_zones_city_id_idx on private.seismic_zones (city_id);

alter table private.seismic_zones enable row level security;

revoke all on private.seismic_zones from anon, authenticated;

create function private.seismic_hazard_at(
  p_location extensions.geography,
  p_code text,
  p_snap_m integer
)
returns table (ag_g numeric, city_id uuid, distance_m double precision)
language sql
stable
set search_path = ''
as $$
  select z.ag_g, z.city_id, extensions.st_distance(z.area, p_location)
  from private.seismic_zones z
  where z.code = p_code
    and extensions.st_dwithin(z.area, p_location, p_snap_m)
  order by 3, z.ag_g desc
  limit 1;
$$;

create function private.seismic_city_hazards(p_code text)
returns table (city_id uuid, slug text, ag_g numeric, zone_count integer)
language sql
stable
set search_path = ''
as $$
  select c.id, c.slug, center_zone.ag_g, zones.zone_count
  from public.cities c
  cross join lateral (
    select z.ag_g
    from private.seismic_zones z
    where z.code = p_code and z.city_id = c.id
    order by extensions.st_distance(z.area, c.center), z.ag_g desc
    limit 1
  ) as center_zone
  cross join lateral (
    select count(*)::integer as zone_count
    from private.seismic_zones z
    where z.code = p_code
      and z.city_id = c.id
      and extensions.st_intersects(z.area, c.boundary)
  ) as zones
  where c.has_online_coverage
  order by center_zone.ag_g desc, c.position;
$$;

